#include <iomanip>
#include <iostream>

int main()
{
    double km{};
    double litres{};
    std::cin >> km >> litres;

    std::cout << std::fixed;
    std::cout << std::setprecision(1) << litres / km * 100 << " L/100km\n";
    std::cout << std::setprecision(2) << km / litres << " km/L\n";
    return 0;
}
